from pathlib import Path

names=['A · Split workbench','B · Focused notebook','C · Visual inspector','D · Request console','E · Decision matrix','F · Image folio']
descs=['Edit and inspect side by side','A calm, sequential workspace','Put image decisions at the center','Request above, response below','Every type gets its own module','Image and question in balance']
photo='<div class="photo"><img src="assets/sample-mug.jpg" alt="Sample mug photograph"><span class="box">product_region</span></div>'
questions='<div class="question">category <b>Choice</b></div><div class="question">listing_quality <b>Score</b></div><div class="question">product_present <b>Noul</b></div><div class="question">product_region <b>Box</b></div>'
result='<h3>Decision results</h3><strong>Home & living</strong><div class="bar"></div><p>Product present <b>98%</b></p><p>Listing quality <b>3.6 / 4</b></p>'
state='<h3>Listing state</h3><pre>{\n  "title": "Ceramic mug",\n  "condition": "new",\n  "photo": "@product"\n}</pre>'
nav='<aside><b>kimeru</b><button>＋ New playground</button><p>Playgrounds</p><p class="active">Product listing review</p><p>Support routing</p><p>Run history</p><p>Connections</p></aside>'
top='<header><b>Product listing review</b><span>Jev 1.14 <button>Run preview</button></span></header>'
layouts=[
 nav+'<main>'+top+'<div class="split"><section>'+state+'<h3>Questions</h3>'+questions+'</section><section>'+result+photo+'</section></div></main>',
 nav+'<main>'+top+'<div class="notebook"><h1>Product listing review</h1><p>Personal playground · Sample results</p><section>'+state+photo+'</section><section>'+questions+'</section><footer>'+result+'</footer></div></main>',
 '<main>'+top+'<div class="canvas"><section><h3>Questions</h3>'+questions+'<button>＋ Add question</button></section><section>'+photo+'<footer>'+result+'</footer></section></div></main>',
 '<aside class="rail">K<br>＋<br>▤<br>⌘</aside><main>'+top+'<div class="request"><p>Personal TypeSafe / Jev 1.14</p><p>State　 Questions　 Assets</p>'+state+questions+'<footer>'+result+'</footer></div></main>',
 '<main>'+top+'<div class="matrix"><section>'+state+'</section><section>'+photo+'</section><section>'+result+'</section><section><h3>Question set</h3>'+questions+'</section></div></main>',
 '<main>'+top+'<div class="folio"><section>'+photo+'<div class="floating">Product present <b>98%</b></div></section><section><h1>Inspect a decision.</h1>'+state+questions+'</section></div></main>'
]
css='''*{box-sizing:border-box}body{margin:0;background:#eee;font:14px Inter,Arial,sans-serif;color:#171717}h1{font-size:30px;letter-spacing:-1px}h2{font-size:18px;margin:0}h3{font-size:16px;margin:0 0 18px}p{line-height:1.5;color:#626262}button{background:#d22a7d;border:0;color:white;padding:12px;font:inherit;border-radius:4px} .intro{padding:28px 36px;background:white;border-bottom:1px solid #ddd}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;padding:28px 36px}.card{min-width:0}.preview{height:300px;overflow:hidden;border:1px solid #ccc;background:white}.ui{display:flex;width:1440px;height:900px;transform:scale(.33333);transform-origin:top left;font-size:18px}.caption{padding:12px 0}.caption p{margin:5px 0}aside{width:235px;background:#f7f7f7;padding:26px;flex-shrink:0;border-right:1px solid #ddd}aside>b{font-size:32px;letter-spacing:-2px}aside button{margin:32px 0 20px;width:100%;font-size:16px}.active{background:#fce7f3;color:#9e1656;padding:12px;margin-left:-12px;margin-right:-12px}main{flex:1;min-width:0}header{height:82px;border-bottom:1px solid #ddd;display:flex;align-items:center;justify-content:space-between;padding:20px 32px}header span{display:flex;align-items:center;gap:24px}.split{display:grid;grid-template-columns:1fr 1fr;height:818px}.split>section{padding:32px;border-right:1px solid #ddd}.question{padding:22px 0;border-bottom:1px solid #ddd;display:flex;justify-content:space-between}.question b{font-size:14px;background:#f5e5ed;color:#93134d;padding:5px 10px}.bar{width:90%;height:12px;background:#d22a7d;margin:22px 0}.photo{position:relative;background:#e5e0da;height:280px;display:grid;place-items:center;color:#625b52;margin:24px 0}.photo:before{content:"";width:90px;height:125px;background:#fdfcf7;border:2px solid #bbb4a8;border-radius:8px 8px 20px 20px}.box{position:absolute;left:29%;top:22%;width:43%;height:62%;border:3px solid #d22a7d;font-size:14px;color:#a41d62;padding:5px}pre{font:18px/1.7 monospace;background:#fafafa;padding:22px;color:#575757}.notebook{max-width:850px;margin:auto;padding:24px 0}.notebook section{padding:20px 28px;border:1px solid #ddd;margin:18px 0}.notebook .photo{height:140px;float:right;width:250px;margin-top:-185px}.notebook .photo:before{height:75px;width:55px}.notebook footer{padding:20px;background:#fdf2f8}.canvas{display:grid;grid-template-columns:300px 1fr;height:818px}.canvas>section{padding:30px}.canvas .photo{height:480px}.canvas .photo:before{height:220px;width:180px}.canvas footer{display:flex;align-items:center;gap:24px}.canvas footer .bar{display:none}.c2{background:#171717;color:#fafafa}.c2 header,.c2 .question{border-color:#444}.c2 .photo{background:#383532}.c2 p{color:#ccc}.c2 .question b{background:#38222c;color:#f8aed1}.c2 .box{color:#f8aed1}.rail{width:72px;line-height:80px;text-align:center;padding:10px}.request{padding:28px}.request footer{padding:25px;border-top:1px solid #ddd;display:flex;gap:25px;align-items:center}.request .bar{width:150px}.request pre{height:185px}.request .question{display:inline-flex;width:24%;padding:20px}.matrix{display:grid;grid-template-columns:1fr 1fr;gap:18px;padding:30px}.matrix section{padding:30px;border:2px solid #171717}.matrix section:nth-child(3){background:#fce7f3}.matrix .photo{margin:0;height:225px}.folio{display:grid;grid-template-columns:1.2fr 1fr;padding:50px;gap:60px}.folio .photo{height:590px}.folio .photo:before{height:230px;width:180px}.floating{position:relative;background:#fce7f3;border:1px solid #d22a7d;padding:28px;margin:-100px -25px 0 110px;font-size:24px}@media(min-width:1150px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}'''
html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kimeru · Six layout studies</title><style>'+css+'</style><div class="intro"><h1>Six ways to work with a decision.</h1><p>Layout studies · Shared pink / neutral preset · Illustrated sample data</p></div><div class="grid">'
for i,(name,desc,layout) in enumerate(zip(names,descs,layouts)):
 html+=f'<article class="card"><div class="preview"><div class="ui c{i}">{layout}</div></div><div class="caption"><h2>{name}</h2><p>{desc}</p></div></article>'
html+='<style>.photo:before{display:none}.photo img{width:100%;height:100%;object-fit:contain}.box{left:12%;top:49%;width:36%;height:39%}</style></div><script>function fit(){document.querySelectorAll(".preview").forEach(p=>{let s=p.clientWidth/1440;p.querySelector(".ui").style.transform="scale("+s+")";p.style.height=(900*s)+"px"})}fit();addEventListener("resize",fit)</script></html>'
Path('design-demos/thumbs.html').write_text(html)
